console.log("AI Tweet Filter: Background script running");chrome.runtime.onInstalled.addListener(()=>{const r=crypto.randomUUID();chrome.storage.local.get(["userId"],s=>{s.userId||chrome.storage.local.set({userId:r,enabled:!0,threshold:.75,stats:{scanned:0,hidden:0},userApiKey:""})})});chrome.runtime.onMessage.addListener((r,s,t)=>{if(r.type==="CLASSIFY_TWEETS"){const o="http://localhost:3000/api/classify";return(async()=>{try{const e=await fetch(o,{method:"POST",headers:r.headers,body:JSON.stringify(r.body)});if(!e.ok){t({success:!1,error:e.statusText,status:e.status});return}const a=await e.json();t({success:!0,data:a})}catch(e){console.error("Background API Fetch Error:",e),t({success:!1,error:e.message})}})(),!0}});
